const {
  withAndroidManifest,
  withAppBuildGradle,
  withDangerousMod,
  AndroidConfig,
} = require("expo/config-plugins");
const fs = require("fs");
const path = require("path");

/**
 * Injects the home-screen widget into the Android project during prebuild. The native
 * dirs are gitignored and regenerated by `expo prebuild`, so the canonical widget
 * sources live in the tracked `widget/android/` tree and are copied in here:
 *   - res/ (layouts, drawable, xml, generated widget_theme.xml + values-night) → app res
 *   - the picker's preview layouts, written from the sample library (see widgetPreviews.js)
 *   - a strings file per locale, generated from src/i18n/locales/, for the text
 *     the widgets and the notification channel show before any snapshot exists
 *   - java/ Kotlin, with __PKG__ templated to the resolved variant package, written
 *     under the matching package path
 *   - an AppWidgetProvider <receiver> added to the manifest, and the picker activities
 *   - the Material components library, which the pickers compile against
 *
 * The package differs by variant (com.veloq.app vs com.veloq.app.dev, see app.config.js),
 * which is why the Kotlin uses a __PKG__ placeholder rather than a hardcoded package.
 */

// Quick-Record stays compiled but out of the gallery until the record surface is
// ready. The flag is shared with the iOS plugin so one edit moves both, and on
// this side it drops the standalone receiver and writes the bool the Dashboard
// widget's large layout reads, which carries a record button over the same deep
// link.
const { INCLUDE_RECORD_WIDGET } = require("./widgetFlags");
const { writeAndroidStrings } = require("./nativeStrings");
const { writeWidgetPreviews } = require("./widgetPreviews");

// Summary (all sizes, hero chosen when placed), Latest Activity, Insights (kinds
// chosen when placed), Strength (window chosen when placed), and the Quick-Record
// button. Excluded receivers are actively removed so an incremental prebuild can't
// keep a stale registration. A label names the widget in the gallery; one without
// it shows the application name.
const RECEIVERS = [
  {
    name: ".widget.VeloqWidgetProvider",
    info: "@xml/veloq_widget_info",
    label: "@string/widget_summary_label",
    include: true,
  },
  { name: ".widget.VeloqActivityWidgetProvider", info: "@xml/widget_activity_info", include: true },
  {
    name: ".widget.VeloqInsightsWidgetProvider",
    info: "@xml/widget_insights_info",
    label: "@string/widget_insights_label",
    include: true,
  },
  {
    name: ".widget.VeloqStrengthWidgetProvider",
    info: "@xml/widget_strength_info",
    label: "@string/widget_strength_label",
    include: true,
  },
  {
    name: ".widget.VeloqRecordWidgetProvider",
    info: "@xml/widget_record_info",
    include: INCLUDE_RECORD_WIDGET,
  },
];

// Resources carry `__PKG__` too, not only the Kotlin: `android:configure` on a
// provider info takes a class name in full, and the package is only known here.
function copyDir(src, dest, pkg) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDir(from, to, pkg);
    } else if (entry.name.endsWith(".xml")) {
      fs.writeFileSync(to, fs.readFileSync(from, "utf8").replace(/__PKG__/g, pkg));
    } else {
      fs.copyFileSync(from, to);
    }
  }
}

// The Kotlin cannot read the JS constant, so it reaches the natives as a resource.
// Generated rather than tracked, so there is no second copy to drift.
function writeFlags(resDir) {
  const values = path.join(resDir, "values");
  fs.mkdirSync(values, { recursive: true });
  fs.writeFileSync(
    path.join(values, "widget_flags.xml"),
    `<?xml version="1.0" encoding="utf-8"?>
<resources>
  <bool name="widget_record_enabled">${INCLUDE_RECORD_WIDGET}</bool>
</resources>
`
  );
}

function writeWidgetSources(projectRoot, androidRoot, pkg) {
  const widgetSrc = path.join(projectRoot, "widget", "android");
  const mainSrc = path.join(androidRoot, "app", "src", "main");

      copyDir(path.join(widgetSrc, "res"), path.join(mainSrc, "res"), pkg);
      writeFlags(path.join(mainSrc, "res"));
      writeWidgetPreviews(projectRoot, path.join(mainSrc, "res"));
      writeAndroidStrings(path.join(mainSrc, "res"));

      const javaDest = path.join(mainSrc, "java", pkg.replace(/\./g, "/"), "widget");
      fs.mkdirSync(javaDest, { recursive: true });
      const javaSrc = path.join(widgetSrc, "java");
      const sources = fs.readdirSync(javaSrc);

      // This directory holds nothing but the generated widget sources, so a
      // file no longer in widget/android/java is stale and must go. Copying
      // alone is additive and would keep compiling deleted Kotlin.
      const kept = new Set(sources);
      for (const file of fs.readdirSync(javaDest)) {
        if (!kept.has(file)) fs.rmSync(path.join(javaDest, file), { force: true });
      }

      for (const file of sources) {
        const templated = fs.readFileSync(path.join(javaSrc, file), "utf8").replace(/__PKG__/g, pkg);
        fs.writeFileSync(path.join(javaDest, file), templated);
      }
}

function withWidgetSources(config) {
  return withDangerousMod(config, [
    "android",
    (cfg) => {
      writeWidgetSources(
        cfg.modRequest.projectRoot,
        cfg.modRequest.platformProjectRoot,
        cfg.android?.package || "com.veloq.app"
      );
      return cfg;
    },
  ]);
}

function applyReceivers(app) {
    app.receiver = app.receiver || [];
    for (const { name, include } of RECEIVERS) {
      if (!include) {
        app.receiver = app.receiver.filter((r) => r.$?.["android:name"] !== name);
      }
    }
    for (const { name, info, label, include } of RECEIVERS) {
      if (!include) continue;
      const exists = app.receiver.some((r) => r.$?.["android:name"] === name);
      if (exists) continue;
      app.receiver.push({
        $: {
          "android:name": name,
          "android:exported": "true",
          ...(label ? { "android:label": label } : {}),
        },
        "intent-filter": [
          {
            action: [{ $: { "android:name": "android.appwidget.action.APPWIDGET_UPDATE" } }],
          },
        ],
        "meta-data": [
          {
            $: {
              "android:name": "android.appwidget.provider",
              "android:resource": info,
            },
          },
        ],
      });
    }
}

// The Quick Settings tile rides the same gate as the widget: one record surface
// off means every record surface off. Removed rather than skipped, so an
// incremental prebuild cannot keep a stale registration.
const TILE_SERVICE = ".widget.RecordTileService";

function applyServices(app, include = INCLUDE_RECORD_WIDGET) {
  app.service = app.service || [];
  app.service = app.service.filter((s) => s.$?.["android:name"] !== TILE_SERVICE);
  if (!include) return;
  app.service.push({
    $: {
      "android:name": TILE_SERVICE,
      "android:exported": "true",
      "android:icon": "@drawable/widget_record_roundel",
      "android:label": "@string/app_name",
      "android:permission": "android.permission.BIND_QUICK_SETTINGS_TILE",
    },
    "intent-filter": [
      {
        action: [{ $: { "android:name": "android.service.quicksettings.action.QS_TILE" } }],
      },
    ],
  });
}

// The pickers a placed widget opens. The Record one rides the same gate as the
// widget it configures; the Summary, Insights and Strength ones belong to widgets
// that are always in the gallery. Both are removed rather than skipped, so an incremental prebuild cannot
// keep a stale registration pointing at a class that is no longer compiled.
const SUMMARY_CONFIGURE_ACTIVITY = ".widget.SummaryWidgetConfigureActivity";
const INSIGHTS_CONFIGURE_ACTIVITY = ".widget.InsightsWidgetConfigureActivity";
const STRENGTH_CONFIGURE_ACTIVITY = ".widget.StrengthWidgetConfigureActivity";
const RECORD_CONFIGURE_ACTIVITY = ".widget.RecordWidgetConfigureActivity";

// One theme for every picker, defined in widget/android/res: Material 3 in the brand colours with
// no action bar, since the shared picker frame carries its own toolbar. Without it a picker takes
// the application theme, an AppCompat one with no bar to show its title in.
const CONFIGURE_THEME = "@style/Theme.Veloq.WidgetConfigure";

function configureActivity(name) {
  return {
    $: {
      "android:name": name,
      // The launcher starts it, so it is reachable from outside the app.
      "android:exported": "true",
      "android:excludeFromRecents": "true",
      "android:label": "@string/app_name",
      "android:theme": CONFIGURE_THEME,
    },
    "intent-filter": [
      {
        action: [{ $: { "android:name": "android.appwidget.action.APPWIDGET_CONFIGURE" } }],
      },
    ],
  };
}

function applyActivities(app, includeRecord = INCLUDE_RECORD_WIDGET) {
  const pickers = [
    { name: SUMMARY_CONFIGURE_ACTIVITY, include: true },
    { name: INSIGHTS_CONFIGURE_ACTIVITY, include: true },
    { name: STRENGTH_CONFIGURE_ACTIVITY, include: true },
    { name: RECORD_CONFIGURE_ACTIVITY, include: includeRecord },
  ];
  app.activity = (app.activity || []).filter(
    (a) => !pickers.some((p) => p.name === a.$?.["android:name"])
  );
  for (const { name, include } of pickers) {
    if (include) app.activity.push(configureActivity(name));
  }
}

// The pickers' toolbar, ticks, radios and buttons are Material components. The library already
// reaches the app's runtime classpath through other modules' `implementation` dependencies, which
// do not put it on the app's compile classpath, so the app declares it itself at the version the
// graph resolves.
const MATERIAL_DEPENDENCY = "com.google.android.material:material:1.13.0";

function applyMaterialDependency(contents) {
  if (contents.includes("com.google.android.material:material:")) return contents;
  if (!/^dependencies\s*\{/m.test(contents)) {
    throw new Error("with-android-widget: app/build.gradle has no dependencies block");
  }
  return contents.replace(
    /^dependencies\s*\{/m,
    `dependencies {\n    implementation "${MATERIAL_DEPENDENCY}"`
  );
}

function withMaterialComponents(config) {
  return withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = applyMaterialDependency(mod.modResults.contents);
    return mod;
  });
}

function withWidgetReceiver(config) {
  return withAndroidManifest(config, (mod) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(mod.modResults);
    applyReceivers(app);
    applyServices(app);
    applyActivities(app);
    return mod;
  });
}

module.exports = function withAndroidWidget(config) {
  config = withWidgetReceiver(config);
  config = withWidgetSources(config);
  config = withMaterialComponents(config);
  return config;
};

module.exports.INCLUDE_RECORD_WIDGET = INCLUDE_RECORD_WIDGET;
module.exports.applyReceivers = applyReceivers;
module.exports.applyActivities = applyActivities;
module.exports.applyServices = applyServices;
module.exports.applyMaterialDependency = applyMaterialDependency;
module.exports.CONFIGURE_THEME = CONFIGURE_THEME;
module.exports.MATERIAL_DEPENDENCY = MATERIAL_DEPENDENCY;
module.exports.writeWidgetSources = writeWidgetSources;
